@Module({
  imports: [ExternalCommandModule, DatabaseModule, AgentModule],
  controllers: [],
  providers: [RefreshTokens, ConfigurationTask, AgentRun],
  get exports() {
    return [...this.imports, ...this.providers];
  },
})
